import{Link}from'react-router-dom';import{ArrowRight}from'lucide-react';import{Product}from'../data/products';import ProductCard from'./ProductCard';
export default function ProductSection({eyebrow,title,description,items,viewAll,className='',compact=false}:{eyebrow?:string;title:string;description?:string;items:Product[];viewAll?:string;className?:string;compact?:boolean}){return <section className={`product-system-section ${className}`}><div className="section-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2>{description&&<p>{description}</p>}</div>{viewAll&&<Link to={viewAll}>View all <ArrowRight/></Link>}</div>{items.length?<div className={`product-grid ${compact?'compact-products':''}`}>{items.map(p=><ProductCard key={p.id} p={p}/>)}</div>:<div className="product-section-empty"><h3>No products available</h3><p>Inventory matching this collection will appear here when available.</p><Link className="btn outline" to="/shop">Browse the complete catalog</Link></div>}</section>}
