import{useState}from'react';import{useParams,Link,useSearchParams}from'react-router-dom';import{ArrowRight,Check,Search}from'lucide-react';import{brands,categories,products}from'../data/products';import ProductCard from'../components/ProductCard';import ProductSection from'../components/ProductSection';import{useStore}from'../context/Store';import{getSavedProducts}from'../utils/productSelectors';import{appendAdminRow}from'../data/siteConfig';import BrandLogo from'../components/BrandLogo';
const data:Record<string,{title:string;eyebrow:string;intro:string}>={about:{title:'Distribution experience, reimagined.',eyebrow:'OUR COMPANY',intro:'Nearly three decades of offline wholesale expertise, now brought into a clearer, more capable digital experience.'},'why-choose-us':{title:'A wholesale partner that earns its place.',eyebrow:'WHY MERIDIAN',intro:'Professional sourcing, practical operations and thoughtful support—organized around the way modern businesses buy.'},'how-it-works':{title:'Wholesale made clear.',eyebrow:'HOW IT WORKS',intro:'From business verification to reordering, every step is designed to make purchasing more efficient.'},contact:{title:'Let’s talk business.',eyebrow:'CONTACT US',intro:'Choose the team that can best help with your wholesale inquiry.'},resources:{title:'Practical perspective for modern retail.',eyebrow:'RESOURCES & INSIGHTS',intro:'Guides, buying ideas and category intelligence for wholesale businesses.'},faq:{title:'Answers, without the runaround.',eyebrow:'FREQUENTLY ASKED QUESTIONS',intro:'Straightforward information about accounts, ordering, pricing and fulfillment.'},brands:{title:'Discover our brand portfolio.',eyebrow:'SHOP BY BRAND',intro:'Browse a curated mix of emerging and established suppliers. Brand relationship claims are displayed only when verified.'},categories:{title:'Shop your way.',eyebrow:'PRODUCT CATEGORIES',intro:'Build a relevant, balanced assortment across key beauty and personal care categories.'}};
const legal=['privacy-policy','terms-conditions','cookie-policy','trademark-disclaimer','accessibility','shipping-delivery','returns-policies','payment-information'];
export default function InfoPage(){const{page=''}=useParams();const d=data[page];if(page==='wishlist')return <Wishlist/>;if(legal.includes(page)||page==='forgot-password'||page==='track-order')return <Simple title={page.replaceAll('-',' ')}/>;if(!d)return <Simple title={page.replaceAll('-',' ')}/>;if(page==='brands')return <Listing type="brands" d={d}/>;if(page==='categories')return <Listing type="categories" d={d}/>;return <div className="info-page"><section className="info-hero"><div className="container"><span className="eyebrow">{d.eyebrow}</span><h1>{d.title}</h1><p>{d.intro}</p></div></section>{page==='about'&&<><section className="story container"><div><span className="eyebrow">OUR STORY</span><h2>Relationships first.<br/>Technology in service of them.</h2></div><div><p>Meridian Supply Co. is a demonstration brand representing an established American distributor moving a long-standing wholesale operation online. The platform is built around enduring principles: dependable service, commercial judgment and respect for the businesses we serve.</p><p>Our next chapter combines that operating experience with faster discovery, protected account pricing and practical tools for repeat purchasing.</p></div></section><Feature/></>}{page==='why-choose-us'&&<Feature/>}{page==='how-it-works'&&<section className="timeline container">{['Apply for an account','Business verification','Access wholesale pricing','Build your case-level order','Checkout on your terms','Fulfillment & tracking','Simple reordering'].map((x,i)=><div key={x}><b>{String(i+1).padStart(2,'0')}</b><h2>{x}</h2><p>{i===0?'Share your business and resale information through our guided application.':'A clear, B2B-focused step supported by your wholesale account workspace.'}</p></div>)}</section>}{page==='contact'&&<Contact/>}{page==='resources'&&<Resources/>}{page==='faq'&&<FAQ/>}<section className="final-cta container"><h2>Ready to move forward?</h2><div><Link className="btn primary" to="/apply">Apply for access</Link><Link className="btn outline" to="/shop">Browse catalog</Link></div></section></div>}
function Listing({type,d}:any){const[params]=useSearchParams();const[q,setQ]=useState(params.get('q')||'');const arr=(type==='brands'?brands:categories).filter(x=>x.toLowerCase().includes(q.toLowerCase()));return <div className="info-page"><section className="info-hero"><div className="container"><span className="eyebrow">{d.eyebrow}</span><h1>{d.title}</h1><p>{d.intro}</p></div></section><section className="listing container"><div className="listing-toolbar"><div className="listing-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={`Search ${type}`}/>{q&&<button onClick={()=>setQ('')}>Clear</button>}</div><span>{arr.length} {type} found</span></div>{arr.length?<div className="brand-grid">{arr.map((x:string,i:number)=><Link to={type==='brands'?'/brand/'+x.toLowerCase().replace(/[^a-z0-9]+/g,'-'):'/category/'+x.toLowerCase().replace(/[^a-z0-9]+/g,'-')} key={x}>{type==='brands'?<BrandLogo brand={x} variant="compact"/>:<span>{String(i+1).padStart(2,'0')}</span>}<h3>{x}</h3><p>{products.filter(p=>(type==='brands'?p.brand:p.category)===x).length} products</p><b>Explore <ArrowRight/></b></Link>)}</div>:<div className="listing-empty"><h2>No matching {type}</h2><p>Try a broader name or clear the current search.</p><button className="btn outline" onClick={()=>setQ('')}>Clear search</button></div>}</section></div>}
function Feature(){return <section className="feature-band"><div className="container"><div><span className="eyebrow">OUR OPERATING PRINCIPLES</span><h2>What good distribution should feel like.</h2></div><div className="feature-list">{['Experience that informs better decisions','Assortments built for real retail environments','Protected B2B pricing and account controls','Support from people who understand wholesale'].map(x=><p key={x}><Check/>{x}</p>)}</div></div></section>}
function Contact(){const[sent,setSent]=useState(false);return <section className="contact container"><div><h2>How can we help?</h2>{['New wholesale accounts','Existing customer support','Sales & product inquiries','General business inquiries'].map(x=><p key={x}><b>{x}</b><span>We’ll route your message to the appropriate distribution team.</span></p>)}</div>{sent?<div className="contact-success"><span>✓</span><h2>Inquiry received</h2><p>Your reference has been created. A production deployment will route this request to the responsible account or operations team.</p><button className="btn outline" onClick={()=>setSent(false)}>Send another inquiry</button></div>:<form onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);appendAdminRow('inquiries',[`INQ-${Math.floor(3000+Math.random()*900)}`,String(fd.get('business')||'Business inquiry'),String(fd.get('email')||''),String(fd.get('type')||'General inquiry'),'New']);setSent(true)}}><div className="form-grid"><label>Full name<input required/></label><label>Business email<input name="email" required type="email"/></label><label>Business name<input name="business" required/></label><label>Inquiry type<select name="type"><option>General inquiry</option><option>Product availability</option><option>Sales and quotation</option><option>Order support</option><option>Account support</option></select></label><label>Order or account reference<input placeholder="If applicable"/></label><label>Preferred response<select><option>Email</option><option>Phone</option></select></label><label className="full">How can we help?<textarea rows={6} required/></label></div><button className="btn dark">Submit inquiry</button></form>}</section>}
function Resources(){return <section className="articles container">{['The practical guide to wholesale case packs','Building a beauty assortment with intention','Five signals to watch when planning seasonal inventory'].map((x,i)=><article key={x}><span>WHOLESALE INSIGHTS · {5+i} MIN READ</span><div></div><h2>{x}</h2><p>Clear, useful perspective for independent retailers and growing beauty businesses.</p><Link to="/resources">Read article →</Link></article>)}</section>}
function FAQ(){return <section className="faq container">{[['Who can purchase wholesale?','Qualified retailers, salons, ecommerce sellers and other approved businesses may apply.'],['How do I see wholesale pricing?','Pricing is protected and visible after your business account is approved.'],['Do I need a resale certificate?','Requirements vary by jurisdiction, but a valid resale certificate is generally needed for tax-exempt wholesale purchasing.'],['Is there a minimum order?','Minimums and case packs are displayed at product and cart level for approved buyers.'],['How long does approval take?','Timing depends on the completeness of submitted business documentation.'],['How does shipping work?','Available methods and freight estimates are shown during checkout.']].map(([q,a])=><details key={q}><summary>{q}<span>+</span></summary><p>{a}</p></details>)}</section>}
function Wishlist(){const{saved}=useStore();const items=getSavedProducts(saved);return <div className="saved-page"><section className="catalog-title container"><p>BUYER WORKSPACE / SAVED PRODUCTS</p><h1>Saved products</h1><span>Maintain a focused shortlist for comparison, quotation and future ordering.</span></section><div className="container section"><ProductSection title={items.length?`${items.length} saved ${items.length===1?'product':'products'}`:'Your shortlist is ready when you are'} description={items.length?'Selections are presented through the same product system used throughout the marketplace.':'Save products from catalog cards and product pages to build a reusable buying shortlist.'} items={items} viewAll="/shop"/></div></div>}
function Simple({title}:{title:string}){const key=title.toLowerCase();if(key==='forgot password')return <UtilityForm type="password"/>;if(key==='track order')return <UtilityForm type="tracking"/>;const policies:Record<string,{intro:string;sections:[string,string][]}>={
'privacy policy':{intro:'How business, account and transaction information is handled across the wholesale platform.',sections:[['Information we collect','Business application details, account contacts, delivery addresses, order records and support communications may be collected to operate the distribution relationship.'],['How information is used','Information supports account verification, pricing access, fulfillment, customer service, fraud prevention and legal compliance.'],['Data choices and retention','Approved procedures should allow authorized users to review account information and submit privacy requests. Final retention periods must align with applicable law and company policy.']]},
'terms conditions':{intro:'Commercial terms governing access to the wholesale platform and business purchasing tools.',sections:[['Business eligibility','Platform access is intended for qualified businesses. Account approval, resale documentation and purchasing authority may be required.'],['Orders and availability','Orders remain subject to inventory confirmation, commercial terms, pricing validation and acceptance by the distributor.'],['Intellectual property','Brand names and trademarks remain the property of their respective owners. No relationship should be inferred unless specifically verified.']]},
'cookie policy':{intro:'Information about cookies and similar technologies used to operate the platform.',sections:[['Essential technologies','Essential storage supports account sessions, cart persistence, security and platform preferences.'],['Analytics and preferences','Optional analytics should be activated only through an approved consent process.'],['Managing choices','A production deployment should provide a consent manager appropriate to the markets served.']]},
'trademark disclaimer':{intro:'Clear disclosure regarding third-party brands, products and intellectual property.',sections:[['Third-party marks','All third-party product names, trademarks and logos belong to their respective owners.'],['Relationship statements','Product display does not itself establish authorization, endorsement, exclusivity or an official distribution relationship.'],['Verification controls','Authorization badges and relationship descriptions must remain disabled until supporting documentation is reviewed and approved.']]},
'accessibility':{intro:'Our approach to an inclusive wholesale purchasing experience.',sections:[['Digital access','The platform is designed around semantic structure, keyboard navigation, visible focus, form labels and readable contrast.'],['Ongoing improvement','Accessibility should be reviewed through automated and manual testing as the platform and content evolve.'],['Assistance','Customers who encounter a barrier may contact support for assistance with account and ordering tasks.']]},
'shipping delivery':{intro:'How wholesale orders move from inventory confirmation to business delivery.',sections:[['Available methods','Ground, expedited and scheduled freight options may be presented according to order size, destination and account eligibility.'],['Processing and lead time','Dispatch estimates are displayed at product and checkout level but remain subject to inventory and order review.'],['Freight and delivery','Final charges, carrier details and delivery appointments are confirmed before fulfillment when required.']]},
'returns policies':{intro:'A structured process for reporting and resolving eligible wholesale-order issues.',sections:[['Inspection','Business customers should inspect deliveries promptly and retain shipping, carton and product documentation.'],['Return authorization','Returns require review and authorization. Eligibility may depend on category, product condition, reason and commercial terms.'],['Damages and discrepancies','Shortages, damage or incorrect items should be reported with order references and supporting photographs.']]},
'payment information':{intro:'Payment methods and commercial terms supported by the checkout architecture.',sections:[['Payment methods','The platform is prepared for business cards, ACH transfers, purchase orders and approved account terms.'],['Credit and terms','Payment terms require separate review and should not be represented as approved until underwriting is complete.'],['Security','Production payments must be processed through compliant payment providers; sensitive card information should not be stored by this frontend.']]}}
;const policy=policies[key]||{intro:'Operational information for qualified wholesale customers and distribution partners.',sections:[['Overview','This area provides structured business information for platform users.'],['Account support','Account-specific questions should include the relevant business, order or product reference.'],['Verification','Final operational details are confirmed through the responsible distribution team.']] as [string,string][]};return <div className="info-page"><section className="info-hero"><div className="container"><span className="eyebrow">DISTRIBUTION INFORMATION</span><h1 style={{textTransform:'capitalize'}}>{title}</h1><p>{policy.intro}</p></div></section><section className="legal container"><div className="policy-summary"><b>Business policy center</b><span>Structured for wholesale accounts, orders and distribution operations.</span></div>{policy.sections.map(([h,p])=><article key={h}><h2>{h}</h2><p>{p}</p></article>)}<div className="legal-contact"><h2>Need clarification?</h2><p>Contact the appropriate account or operations team for policy questions related to a specific order.</p><Link className="btn dark" to="/contact">Contact support</Link></div></section></div>}
function UtilityForm({type}:{type:'password'|'tracking'}){const[done,setDone]=useState(false);return <div className="utility-form-page"><section><span className="eyebrow">{type==='password'?'ACCOUNT SECURITY':'ORDER VISIBILITY'}</span><h1>{type==='password'?'Reset your password':'Track a wholesale order'}</h1><p>{type==='password'?'Enter the business email associated with your account.':'Enter the order reference and purchasing email to view current status.'}</p>{done?<div className="utility-success"><b>Request received</b><p>{type==='password'?'If the account exists, password-reset instructions will be sent through the configured email service.':'The tracking request is ready to connect to live carrier and order data.'}</p></div>:<form onSubmit={e=>{e.preventDefault();setDone(true)}}><label>{type==='password'?'Business email':'Order number'}<input required placeholder={type==='password'?'buyer@company.com':'MS-10482'}/></label>{type==='tracking'&&<label>Purchasing email<input required type="email"/></label>}<button className="btn dark">{type==='password'?'Send secure reset link':'View order status'}</button></form>}<Link to={type==='password'?'/login':'/account'}>← Return to {type==='password'?'sign in':'buyer dashboard'}</Link></section><aside><b>{type==='password'?'Secure account access':'Distribution visibility'}</b><p>{type==='password'?'Reset links should be time-limited and delivered only through the verified account email.':'Approved customers can monitor processing, dispatch, carrier events and delivery documentation from one workspace.'}</p></aside></div>}
